// TI SimpleLink ADCs are 12-bit hardware
#define TI_ADC_RESOLUTION_BITS  12
#define TI_ADC_MAX_RAW_VALUE    ((1 << TI_ADC_RESOLUTION_BITS) - 1) // 4095

/**
 * @brief tuya kernel adc init
 *
 * @param[in] port_num: adc port number
 * @param[in] cfg: adc config
 *
 * @return OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 */

OPERATE_RET tkl_adc_init(TUYA_ADC_NUM_E port_num, TUYA_ADC_BASE_CFG_T *cfg)
{
    // --- BEGIN: user implements ---
    if (!is_valid_adc(port_num)) {
        return OPRT_INVALID_PARM;
    }

    // [MAPPING] Look up the real TI hardware index from the Board Config
    // This allows the application to define which Tuya Port (0,1,2) maps to which TI ADC instance.
    int16_t ti_adc_index = tkl_hw_get_adc_index((uint8_t)port_num);

    // If result is negative, the Application did not map this port.
    if (ti_adc_index < 0) {
        return OPRT_NOT_SUPPORTED;
    }

    // If already open, close it first to allow re-config
    if (g_adc_handles[port_num] != NULL) {
        ADC_close(g_adc_handles[port_num]);
        g_adc_handles[port_num] = NULL;
    }

    // Initialize the Global ADC Driver (safe to call multiple times)
    ADC_init();

    ADC_Params params;
    ADC_Params_init(&params);

    // Tuya Config Mapping:
    // TI Drivers are usually blocking/single-shot by default.
    // We ignore 'cfg->mode' because 'ADC_convert' handles the timing logic.
    
    // Open the ADC instance
    // Note: We use the retrieved ti_adc_index instead of the Tuya port_num
    g_adc_handles[port_num] = ADC_open(ti_adc_index, &params);

    if (g_adc_handles[port_num] == NULL) {
        return OPRT_COM_ERROR;
    }

    return OPRT_OK;
    // --- END: user implements ---
}

