/**
 * @brief adc read
 *
 * @param[in] port_num: adc port number
 * @param[out] buff: points to the list of data read from the ADC register
 * @param[in] len:  buff len
 *
 * @return OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 */
OPERATE_RET tkl_adc_read_data(TUYA_ADC_NUM_E port_num, int32_t *buff, uint16_t len)
{
    // --- BEGIN: user implements ---
    if (!is_valid_adc(port_num) || g_adc_handles[port_num] == NULL || buff == NULL) {
        return OPRT_INVALID_PARM;
    }

    int32_t result = OPRT_OK;
    uint16_t rawValue;
    int_fast16_t res;

    // TI Drivers perform one conversion per call (Blocking)
    for (uint16_t i = 0; i < len; i++) {
        res = ADC_convert(g_adc_handles[port_num], &rawValue);

        if (res == ADC_STATUS_SUCCESS) {
            buff[i] = (int32_t)rawValue;
        } else {
            result = OPRT_COM_ERROR;
            // If one fails, we stop to return error
            break; 
        }
    }

    return result;
    // --- END: user implements ---
}

