/**
 * @brief read voltage
 *
 * @param[in] port_num: adc port number
 * @param[out] buff: points to the list of calculate voltage,bat : mv
 * @param[in] len:  buff len
 * @return OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 *
 */
OPERATE_RET tkl_adc_read_voltage(TUYA_ADC_NUM_E port_num, int32_t *buff, uint16_t len)
{
    // --- BEGIN: user implements ---
    if (!is_valid_adc(port_num) || g_adc_handles[port_num] == NULL || buff == NULL) {
        return OPRT_INVALID_PARM;
    }

    uint16_t rawValue;
    int_fast16_t res;
    uint32_t microVolts;

    for (uint16_t i = 0; i < len; i++) {
        // 1. Get Raw Value
        res = ADC_convert(g_adc_handles[port_num], &rawValue);

        if (res == ADC_STATUS_SUCCESS) {
            // 2. Convert Raw to Voltage using TI Helper
            // This function automatically accounts for VRef and Resolution
            microVolts = ADC_convertToMicroVolts(g_adc_handles[port_num], rawValue);
            
            // 3. Convert Microvolts to Millivolts (Tuya wants mV)
            buff[i] = (int32_t)(microVolts / 1000);
        } else {
            return OPRT_COM_ERROR;
        }
    }

    return OPRT_OK;
    // --- END: user implements ---
}